        rtr_order_value_band__standard.effective_tax_rate3 as effective_tax_rate,
        rtr_order_value_band__standard.food_item_lines3 as food_item_lines,
        rtr_order_value_band__standard.drink_item_lines3 as drink_item_lines,
        rtr_order_value_band__standard.food_share_of_lines3 as food_share_of_lines,
        rtr_order_value_band__standard.drink_share_of_lines3 as drink_share_of_lines,
        'STANDARD' as order_value_band,
        rtr_order_value_band__standard.customer_order_number3 as customer_order_number
    from rtr_order_value_band__standard
),

-- UN_ORDER_BANDS · Union · L1861–1978
un_order_bands as (
    -- group EXP_HIGH_BAND
    select
        exp_high_band.order_id,
        exp_high_band.customer_id,
        exp_high_band.location_id,
        exp_high_band.ordered_at_day,
        exp_high_band.order_subtotal,
        exp_high_band.order_tax_paid,
        exp_high_band.order_total,
        exp_high_band.order_cogs,
        exp_high_band.order_gross_profit,
        exp_high_band.order_value_band
    from exp_high_band
    union all
    -- group EXP_STD_BAND
    select
        exp_std_band.order_id,
        exp_std_band.customer_id,
        exp_std_band.location_id,
        exp_std_band.ordered_at_day,
        exp_std_band.order_subtotal,
        exp_std_band.order_tax_paid,
        exp_std_band.order_total,
        exp_std_band.order_cogs,
        exp_std_band.order_gross_profit,
        exp_std_band.order_value_band
    from exp_std_band
),

-- SRT_BEFORE_AGG · Sorter · L1979–1999 · dropped: row order means nothing in a table (decision Q12)
-- SRT_FOR_DISTINCT_CUSTOMER · Sorter · L2091–2111 · dropped: row order means nothing in a table (decision Q12)
-- EXP_MARK_FIRST_CUSTOMER · Expression · L2112–2129
exp_mark_first_customer as (
    select
        un_order_bands.location_id,
        un_order_bands.ordered_at_day,
        un_order_bands.customer_id,
        un_order_bands.order_id,
        un_order_bands.order_total,
        un_order_bands.order_subtotal,
        un_order_bands.order_tax_paid,
        un_order_bands.order_cogs,
        un_order_bands.order_gross_profit,
        un_order_bands.order_value_band,
        /* v_IS_FIRST_CUSTOMER L2127 */ (case when ((/* v_PREV_LOCATION L2124 */ (un_order_bands.location_id) = un_order_bands.location_id and /* v_PREV_DAY L2125 */ (un_order_bands.ordered_at_day) = un_order_bands.ordered_at_day) and /* v_PREV_CUSTOMER L2126 */ (un_order_bands.customer_id) = un_order_bands.customer_id) then 0 else 1 end) as is_first_customer  -- FLAG self_compare L2127: v_IS_FIRST_CUSTOMER compares un_order_bands.location_id, un_order_bands.ordered_at_day, un_order_bands.customer_id with itself: the variables it reads already hold this row's values (they come earlier in port order), so each comparison is true unless the value is NULL
    from un_order_bands
),

-- AGG_BY_LOCATION_DAY · Aggregator · L2000–2026
agg_by_location_day as (
    select
        exp_mark_first_customer.location_id,
        exp_mark_first_customer.ordered_at_day,
        count(exp_mark_first_customer.order_id) as orders_count,
        sum(exp_mark_first_customer.is_first_customer) as unique_customers,
        sum(exp_mark_first_customer.order_total) as revenue_total,
        sum(exp_mark_first_customer.order_subtotal) as subtotal_total,
        sum(exp_mark_first_customer.order_tax_paid) as tax_total,
        sum(exp_mark_first_customer.order_cogs) as cogs_total,
        sum(exp_mark_first_customer.order_gross_profit) as gross_profit_total,
        sum(case when exp_mark_first_customer.order_value_band = 'HIGH' then 1 else 0 end) as high_value_orders
    from exp_mark_first_customer
    group by exp_mark_first_customer.location_id, exp_mark_first_customer.ordered_at_day
),

-- EXP_STORE_KPIS · Expression · L2027–2042
exp_store_kpis as (
    select
        agg_by_location_day.location_id,
        agg_by_location_day.ordered_at_day,
        agg_by_location_day.orders_count,
        agg_by_location_day.unique_customers,
        agg_by_location_day.revenue_total,
        agg_by_location_day.subtotal_total,
        agg_by_location_day.tax_total,
        agg_by_location_day.cogs_total,
        agg_by_location_day.gross_profit_total,
        agg_by_location_day.high_value_orders,
        case when agg_by_location_day.subtotal_total = 0 then 0 else agg_by_location_day.gross_profit_total / agg_by_location_day.subtotal_total end as gross_margin_pct,
        case when agg_by_location_day.orders_count = 0 then 0 else agg_by_location_day.revenue_total / agg_by_location_day.orders_count end as avg_order_value,
        case when agg_by_location_day.orders_count = 0 then 0 else agg_by_location_day.high_value_orders / agg_by_location_day.orders_count end as high_value_orders_pct
    from agg_by_location_day
),

-- SQ_STG_LOCATIONS1 · Source Qualifier · L2043–2060 · reads STG_LOCATIONS (L1014–1020), which another mapping writes: ref() (decision Q5)
sq_stg_locations1 as (
    select
        stg_locations.location_id,
        stg_locations.location_name,
        stg_locations.region
    from {{ ref('stg_locations') }} as stg_locations
),

-- JNR_ADD_LOCATION_INFO · Joiner · L2061–2090 · Master Outer Join
jnr_add_location_info as (
    select
        master.location_id,
        detail.location_name,
        detail.region,
        master.ordered_at_day,
        master.orders_count,
        master.unique_customers,
        master.revenue_total,
        master.subtotal_total,
        master.tax_total,
        master.cogs_total,
        master.gross_profit_total,
        master.gross_margin_pct,
        master.avg_order_value,
        master.high_value_orders,
        master.high_value_orders_pct
    from sq_stg_locations1 as detail
    left join exp_store_kpis as master  -- FLAG master_outer L2081: JNR_ADD_LOCATION_INFO is a Master Outer Join: it keeps every row from SQ_STG_LOCATIONS1 (detail) and only the rows from EXP_STORE_KPIS (master) that match; EXP_STORE_KPIS rows with no match are dropped
        on master.location_id = detail.location_id
),

-- FIL_LOCS · Filter · L2369–2387
fil_locs as (
    select
        jnr_add_location_info.location_id,
        jnr_add_location_info.location_name,
        jnr_add_location_info.region,
        jnr_add_location_info.ordered_at_day,
        jnr_add_location_info.orders_count,
        jnr_add_location_info.unique_customers,
        jnr_add_location_info.revenue_total,
        jnr_add_location_info.subtotal_total,
        jnr_add_location_info.tax_total,
        jnr_add_location_info.cogs_total,
        jnr_add_location_info.gross_profit_total,
        jnr_add_location_info.gross_margin_pct,
        jnr_add_location_info.avg_order_value,
        jnr_add_location_info.high_value_orders,
        jnr_add_location_info.high_value_orders_pct
    from jnr_add_location_info
    where coalesce((not (jnr_add_location_info.location_id is null)), false)  -- NOT ISNULL(LOCATION_ID) (L2385); a row whose condition is NULL is dropped, as in PowerCenter
)

select
    cast(fil_locs.location_id as varchar) as location_id,
    cast(fil_locs.location_name as varchar) as location_name,
    cast(fil_locs.region as varchar) as region,
    cast(fil_locs.ordered_at_day as timestamp) as ordered_at_day,
    cast(fil_locs.orders_count as decimal(15,0)) as orders_count,
    cast(fil_locs.unique_customers as decimal(15,0)) as unique_customers,
    cast(fil_locs.revenue_total as decimal(12,2)) as revenue_total,
    cast(fil_locs.subtotal_total as decimal(12,2)) as subtotal_total,
    cast(fil_locs.tax_total as decimal(12,2)) as tax_total,
    cast(fil_locs.cogs_total as decimal(12,2)) as cogs_total,
    cast(fil_locs.gross_profit_total as decimal(12,2)) as gross_profit_total,
    cast(fil_locs.gross_margin_pct as decimal(10,4)) as gross_margin_pct,  -- FLAG rounds L2555: GROSS_MARGIN_PCT is computed as IIF(SUBTOTAL_TOTAL = 0, 0, GROSS_PROFIT_TOTAL / SUBTOTAL_TOTAL) (L2038), a double at run time because high precision is off, and is rounded to 4 decimal places by the target column GROSS_MARGIN_PCT decimal(10,4) (decision Q11)
    cast(fil_locs.avg_order_value as decimal(12,2)) as avg_order_value,  -- FLAG rounds L2556: AVG_ORDER_VALUE is computed as IIF(ORDERS_COUNT = 0, 0, REVENUE_TOTAL / ORDERS_COUNT) (L2039), a double at run time because high precision is off, and is rounded to 2 decimal places by the target column AVG_ORDER_VALUE decimal(12,2) (decision Q11)
    cast(fil_locs.high_value_orders as decimal(15,0)) as high_value_orders,
    cast(fil_locs.high_value_orders_pct as decimal(10,4)) as high_value_orders_pct  -- FLAG rounds L2558: HIGH_VALUE_ORDERS_PCT is computed as IIF(ORDERS_COUNT = 0, 0, HIGH_VALUE_ORDERS / ORDERS_COUNT) (L2040), a double at run time because high precision is off, and is rounded to 4 decimal places by the target column HIGH_VALUE_ORDERS_PCT decimal(10,4) (decision Q11)
from fil_locs
